import { createHash } from "node:crypto";
import { existsSync, readFileSync, statSync } from "node:fs";
import { gunzipSync } from "node:zlib";

/**
 * Release metadata gate. Runs after the production build (`npm run check`), so it can rely on
 * `font-packs/` and `main.js` being fresh — and it must fail loudly when they are not there
 * instead of crashing with an ENOENT stack trace that reads like a toolchain bug.
 */
const errors = [];

function requireFile(path, hint) {
    if (existsSync(path)) return true;
    errors.push(`${path} is missing — ${hint}`);
    return false;
}

function json(path) {
    return JSON.parse(readFileSync(path, "utf8"));
}

const hasPackage = requireFile("package.json", "this is not the plugin repository root");
const hasManifest = requireFile("manifest.json", "the release cannot be validated without it");
const hasVersions = requireFile("versions.json", "it records the minimum Obsidian version per release");
const hasMain = requireFile("main.js", "run `npm run build` before `npm run release:check`");

const pkg = hasPackage ? json("package.json") : { version: "0.0.0" };
const manifest = hasManifest ? json("manifest.json") : { version: "0.0.0", minAppVersion: "0.0.0" };
const versions = hasVersions ? json("versions.json") : {};

if (pkg.version !== manifest.version) {
    errors.push(`package.json ${pkg.version} != manifest.json ${manifest.version}`);
}
if (process.env.RELEASE_TAG && process.env.RELEASE_TAG !== manifest.version) {
    errors.push(
        `release tag ${process.env.RELEASE_TAG} != manifest version ${manifest.version}`,
    );
}
if (/\bobsidian\b/iu.test(manifest.description ?? "")) {
    errors.push("manifest description must not include the redundant word Obsidian");
}
if (versions[manifest.version] !== manifest.minAppVersion) {
    errors.push(
        `versions.json does not map ${manifest.version} to ${manifest.minAppVersion}`,
    );
}
if (!/^\d+\.\d+\.\d+$/.test(manifest.version)) {
    errors.push(`manifest version ${manifest.version} is not plain x.y.z SemVer`);
}

if (hasMain) {
    const bundle = readFileSync("main.js", "utf8");
    const size = statSync("main.js").size;
    if (!bundle.startsWith("/*\nTHIS IS A GENERATED/BUNDLED FILE")) {
        errors.push("main.js is not the expected production bundle (esbuild banner missing)");
    }
    if (bundle.includes("//# sourceMappingURL=")) {
        errors.push(
            "main.js contains an inline sourcemap: `npm run build` produced a development bundle",
        );
    }
    if (size < 5_000_000) {
        errors.push(`main.js is only ${size} bytes; the production bundle is about 12 MB`);
    }
}
if (requireFile("styles.css", "the plugin ships it")) {
    if (statSync("styles.css").size === 0) errors.push("styles.css is empty");
}

// The changelog is what users read after an update; a release without its section is silent.
if (requireFile("CHANGELOG.md", "every release needs its entry")) {
    const changelog = readFileSync("CHANGELOG.md", "utf8");
    const heading = new RegExp(
        `^##\\s+${manifest.version.replaceAll(".", "\\.")}(?:\\s|$)`,
        "m",
    );
    if (!heading.test(changelog)) {
        errors.push(`CHANGELOG.md has no "## ${manifest.version}" section`);
    }
}

// Font-pack assets: verify every checksum and that the pack metadata agrees with the font
// version the plugin expects at runtime.
let expectedFontVersion = null;
if (requireFile("src/engine/MathJaxConfig.ts", "the engine defines MATHJAX_FONT_VERSION")) {
    const config = readFileSync("src/engine/MathJaxConfig.ts", "utf8");
    expectedFontVersion = /MATHJAX_FONT_VERSION\s*=\s*"([^"]+)"/.exec(config)?.[1] ?? null;
    if (!expectedFontVersion) {
        errors.push("could not read MATHJAX_FONT_VERSION from src/engine/MathJaxConfig.ts");
    }
}
if (requireFile("font-packs/manifest.json", "run `npm run font-packs:generate` first")) {
    for (const pack of json("font-packs/manifest.json")) {
        const path = `font-packs/${pack.fileName}`;
        if (!requireFile(path, "the font-pack manifest lists a file that was not generated")) {
            continue;
        }
        const compressed = readFileSync(path);
        const digest = createHash("sha256").update(compressed).digest("hex");
        if (compressed.byteLength !== pack.compressedBytes) {
            errors.push(`${path} compressed size does not match its manifest`);
        }
        if (digest !== pack.sha256) errors.push(`${path} checksum does not match its manifest`);
        if (gunzipSync(compressed).byteLength !== pack.uncompressedBytes) {
            errors.push(`${path} expanded size does not match its manifest`);
        }
        if (expectedFontVersion && pack.fontVersion !== expectedFontVersion) {
            errors.push(
                `${path} targets font version ${pack.fontVersion}, ` +
                    `but the engine expects ${expectedFontVersion}`,
            );
        }
    }
}

if (errors.length) {
    console.error(errors.map((error) => `- ${error}`).join("\n"));
    process.exit(1);
}
console.log(
    `release metadata valid: Latest MathJax ${manifest.version}, Obsidian >= ${manifest.minAppVersion}`,
);
